namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Description { get; set; } = "";
    public List<string> Ingredients { get; set; } = new();
    public List<string> Steps { get; set; } = new();
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class RecipeSubmission
{
    [Required(ErrorMessage = "Title is required.")]
    public string Title { get; set; } = "";

    [Required(ErrorMessage = "Category is required.")]
    public string Category { get; set; } = "";

    [Required(ErrorMessage = "Description is required.")]
    public string Description { get; set; } = "";

    [Required(ErrorMessage = "Ingredients are required.")]
    public string Ingredients { get; set; } = "";

    [Required(ErrorMessage = "Steps are required.")]
    public string Steps { get; set; } = "";
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Lock _lock = new();
    private int _nextId;

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new Recipe
            {
                Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
                Description = "Fluffy golden pancakes perfect for a lazy weekend morning.",
                Ingredients = new List<string> { "1 cup flour", "2 tbsp sugar", "1 egg", "1 cup milk", "2 tbsp melted butter", "1 tsp baking powder" },
                Steps = new List<string> { "Mix dry ingredients.", "Whisk egg, milk, and butter together.", "Combine wet and dry ingredients.", "Cook on a greased griddle until bubbles form, then flip." },
                AverageRating = 4.5, RatingCount = 10
            },
            new Recipe
            {
                Id = 2, Title = "Avocado Toast", Category = "Breakfast",
                Description = "Simple and delicious avocado toast with a hint of lemon.",
                Ingredients = new List<string> { "2 slices bread", "1 ripe avocado", "1 tbsp lemon juice", "Salt and pepper", "Red pepper flakes" },
                Steps = new List<string> { "Toast the bread.", "Mash avocado with lemon juice, salt, and pepper.", "Spread on toast and sprinkle with red pepper flakes." },
                AverageRating = 4.2, RatingCount = 8
            },
            new Recipe
            {
                Id = 3, Title = "Spaghetti Bolognese", Category = "Main Course",
                Description = "A hearty Italian classic with rich meat sauce.",
                Ingredients = new List<string> { "400g spaghetti", "500g ground beef", "1 onion", "2 cloves garlic", "400g crushed tomatoes", "2 tbsp tomato paste", "Salt, pepper, oregano" },
                Steps = new List<string> { "Cook spaghetti according to package directions.", "Sauté onion and garlic.", "Brown the beef.", "Add tomatoes and paste, simmer 20 minutes.", "Serve sauce over spaghetti." },
                AverageRating = 4.8, RatingCount = 15
            },
            new Recipe
            {
                Id = 4, Title = "Chicken Stir-Fry", Category = "Main Course",
                Description = "Quick and colorful chicken stir-fry with fresh vegetables.",
                Ingredients = new List<string> { "2 chicken breasts", "1 bell pepper", "1 cup broccoli", "2 tbsp soy sauce", "1 tbsp sesame oil", "1 clove garlic", "Cooked rice" },
                Steps = new List<string> { "Slice chicken and vegetables.", "Heat sesame oil in a wok.", "Cook chicken until golden.", "Add vegetables and garlic, stir-fry 5 minutes.", "Add soy sauce and serve over rice." },
                AverageRating = 4.3, RatingCount = 12
            },
            new Recipe
            {
                Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Decadent chocolate cake with a molten center.",
                Ingredients = new List<string> { "200g dark chocolate", "100g butter", "2 eggs", "2 egg yolks", "50g sugar", "1 tbsp flour" },
                Steps = new List<string> { "Melt chocolate and butter together.", "Whisk eggs, yolks, and sugar.", "Fold chocolate mixture into eggs, add flour.", "Pour into greased ramekins.", "Bake at 220°C for 12 minutes." },
                AverageRating = 4.9, RatingCount = 20
            },
            new Recipe
            {
                Id = 6, Title = "Tiramisu", Category = "Desserts",
                Description = "Classic Italian no-bake dessert with coffee and mascarpone.",
                Ingredients = new List<string> { "250g mascarpone", "3 eggs", "100g sugar", "300ml strong coffee", "Ladyfinger biscuits", "Cocoa powder" },
                Steps = new List<string> { "Separate eggs; whisk yolks with sugar.", "Mix mascarpone into yolk mixture.", "Beat egg whites until stiff and fold in.", "Dip ladyfingers in coffee, layer with cream.", "Refrigerate 4 hours, dust with cocoa." },
                AverageRating = 4.7, RatingCount = 18
            }
        };
        _nextId = 7;
    }

    public List<string> GetCategories()
    {
        lock (_lock)
        {
            return _recipes.Select(r => r.Category).Distinct().ToList();
        }
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
        }
    }

    public Recipe? GetRecipe(int id)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r => r.Id == id);
        }
    }

    public Recipe AddRecipe(Recipe recipe)
    {
        lock (_lock)
        {
            recipe.Id = _nextId++;
            _recipes.Add(recipe);
            return recipe;
        }
    }

    public void RateRecipe(int recipeId, int rating)
    {
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is not null)
            {
                var totalRating = recipe.AverageRating * recipe.RatingCount + rating;
                recipe.RatingCount++;
                recipe.AverageRating = totalRating / recipe.RatingCount;
            }
        }
    }
}

