@page "/"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>RecipeShare Community</PageTitle>

<div class="welcome-banner">
    <h1>Welcome to RecipeShare Community</h1>
    <p>Discover, share, and rate delicious recipes from home cooks around the world.</p>
</div>

<h2>Browse by Category</h2>

<div class="category-grid">
    @foreach (var category in RecipeService.GetCategories())
    {
        <a href="recipes/@category" class="category-card">
            <h3>@category</h3>
            <p>@RecipeService.GetRecipesByCategory(category).Count recipe(s)</p>
        </a>
    }
</div>

@page "/recipes/{Category}"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@Category Recipes — RecipeShare</PageTitle>

<h1>@Category</h1>

@{
    var recipes = RecipeService.GetRecipesByCategory(Category ?? "");
}

@if (recipes.Count == 0)
{
    <p>No recipes found in this category.</p>
}
else
{
    <div class="category-grid">
        @foreach (var recipe in recipes)
        {
            <a href="recipe/@recipe.Id" class="recipe-card">
                <h3>@recipe.Title</h3>
                <p>@recipe.Description</p>
                <span class="rating-badge">★ @recipe.AverageRating.ToString("0.0") (@recipe.RatingCount ratings)</span>
            </a>
        }
    </div>
}

@code {
    [Parameter]
    public string? Category { get; set; }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@(recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

@if (recipe is null)
{
    <p>Recipe not found.</p>
}
else
{
    <div class="recipe-detail">
        <h1>@recipe.Title</h1>
        <span class="recipe-category-badge">@recipe.Category</span>
        <p>@recipe.Description</p>

        <h2>Ingredients</h2>
        <ul class="ingredients-list">
            @foreach (var ingredient in recipe.Ingredients)
            {
                <li>@ingredient</li>
            }
        </ul>

        <h2>Steps</h2>
        <ol class="steps-list">
            @foreach (var step in recipe.Steps)
            {
                <li>@step</li>
            }
        </ol>

        <h2>Rating</h2>
        <StarRating RecipeId="@recipe.Id" AverageRating="@recipe.AverageRating" RatingCount="@recipe.RatingCount" />
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeService.GetRecipe(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>Submit a Recipe</h1>

<EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary />

    <div class="mb-3">
        <label for="title" class="form-label">Title</label>
        <InputText id="title" class="form-control" @bind-Value="submission.Title" />
        <ValidationMessage For="() => submission.Title" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="submission.Category">
            <option value="">-- Select a category --</option>
            <option value="Breakfast">Breakfast</option>
            <option value="Main Course">Main Course</option>
            <option value="Desserts">Desserts</option>
        </InputSelect>
        <ValidationMessage For="() => submission.Category" />
    </div>

    <div class="mb-3">
        <label for="description" class="form-label">Description</label>
        <InputTextArea id="description" class="form-control" @bind-Value="submission.Description" />
        <ValidationMessage For="() => submission.Description" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="submission.Ingredients" />
        <ValidationMessage For="() => submission.Ingredients" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="submission.Steps" />
        <ValidationMessage For="() => submission.Steps" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    private RecipeSubmission submission = new();

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = submission.Title,
            Category = submission.Category,
            Description = submission.Description,
            Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
            Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
        };

        var added = RecipeService.AddRecipe(recipe);
        Navigation.NavigateTo($"/recipe/{added.Id}");
    }
}

